#include "common.h"

#include <algorithm>
#include <cctype>

std::string NumToString(UInt64 v)
{
  char buf[32];
  unsigned pos = 32;
  buf[--pos] = 0;
  if (v == 0)
    buf[--pos] = '0';
  while (v)
  {
    buf[--pos] = (char)('0' + (unsigned)(v % 10));
    v /= 10;
  }
  return std::string(buf + pos);
}

std::string NumToStringPad(UInt64 v, unsigned width)
{
  std::string s = NumToString(v);
  if (s.size() < width)
    s.insert(s.begin(), width - s.size(), ' ');
  return s;
}

std::string NumToStringSpaced(UInt64 v) { return NumToString(v); }

static const char * const kHexUp = "0123456789ABCDEF";

std::string HexU32(UInt32 v)
{
  std::string s(8, '0');
  for (int i = 7; i >= 0; i--) { s[(size_t)i] = kHexUp[v & 0xF]; v >>= 4; }
  return s;
}

std::string HexU64(UInt64 v)
{
  std::string s(16, '0');
  for (int i = 15; i >= 0; i--) { s[(size_t)i] = kHexUp[v & 0xF]; v >>= 4; }
  return s;
}

std::string ToLowerAscii(const std::string &s)
{
  std::string r(s);
  for (size_t i = 0; i < r.size(); i++)
  {
    char c = r[i];
    if (c >= 'A' && c <= 'Z') r[i] = (char)(c - 'A' + 'a');
  }
  return r;
}

std::string ToUpperAscii(const std::string &s)
{
  std::string r(s);
  for (size_t i = 0; i < r.size(); i++)
  {
    char c = r[i];
    if (c >= 'a' && c <= 'z') r[i] = (char)(c - 'a' + 'A');
  }
  return r;
}

bool IsEqualNoCase(const std::string &a, const std::string &b)
{
  if (a.size() != b.size()) return false;
  for (size_t i = 0; i < a.size(); i++)
  {
    char c1 = a[i], c2 = b[i];
    if (c1 >= 'A' && c1 <= 'Z') c1 = (char)(c1 - 'A' + 'a');
    if (c2 >= 'A' && c2 <= 'Z') c2 = (char)(c2 - 'A' + 'a');
    if (c1 != c2) return false;
  }
  return true;
}

bool StringStartsWithNoCase(const std::string &s, const std::string &prefix)
{
  if (s.size() < prefix.size()) return false;
  return IsEqualNoCase(s.substr(0, prefix.size()), prefix);
}

std::vector<std::string> SplitString(const std::string &s, char sep)
{
  std::vector<std::string> res;
  std::string cur;
  for (size_t i = 0; i < s.size(); i++)
  {
    if (s[i] == sep) { res.push_back(cur); cur.clear(); }
    else cur += s[i];
  }
  res.push_back(cur);
  return res;
}

std::string KibString(UInt64 size)
{
  // 7-Zip prints "<n> bytes (<x> KiB)" where the KiB value is rounded up,
  // switching to larger units once the value no longer fits in 4 digits.
  static const char * const kUnits[] = { "KiB", "MiB", "GiB", "TiB", "PiB", "EiB" };
  unsigned i = 0;
  UInt64 v = size;
  for (;;)
  {
    UInt64 t = (v >> 10) + ((v & 0x3FF) != 0 ? 1 : 0);
    if (t < 10000 || i + 1 >= 6) { v = t; break; }
    v = t;
    i++;
  }
  return NumToString(v) + " " + kUnits[i];
}

std::vector<UInt16> Utf8ToUtf16(const std::string &s)
{
  std::vector<UInt16> res;
  size_t i = 0;
  const size_t n = s.size();
  while (i < n)
  {
    Byte c = (Byte)s[i++];
    UInt32 cp;
    if (c < 0x80) cp = c;
    else if ((c & 0xE0) == 0xC0 && i < n) { cp = (UInt32)(c & 0x1F) << 6; cp |= (Byte)s[i++] & 0x3F; }
    else if ((c & 0xF0) == 0xE0 && i + 1 < n)
    {
      cp = (UInt32)(c & 0x0F) << 12;
      cp |= (UInt32)((Byte)s[i++] & 0x3F) << 6;
      cp |= (Byte)s[i++] & 0x3F;
    }
    else if ((c & 0xF8) == 0xF0 && i + 2 < n)
    {
      cp = (UInt32)(c & 0x07) << 18;
      cp |= (UInt32)((Byte)s[i++] & 0x3F) << 12;
      cp |= (UInt32)((Byte)s[i++] & 0x3F) << 6;
      cp |= (Byte)s[i++] & 0x3F;
    }
    else cp = c;

    if (cp >= 0x10000 && cp <= 0x10FFFF)
    {
      cp -= 0x10000;
      res.push_back((UInt16)(0xD800 + (cp >> 10)));
      res.push_back((UInt16)(0xDC00 + (cp & 0x3FF)));
    }
    else
      res.push_back((UInt16)cp);
  }
  return res;
}

std::string Utf16ToUtf8(const UInt16 *data, size_t len)
{
  std::string res;
  for (size_t i = 0; i < len; i++)
  {
    UInt32 cp = data[i];
    if (cp >= 0xD800 && cp < 0xDC00 && i + 1 < len)
    {
      UInt32 c2 = data[i + 1];
      if (c2 >= 0xDC00 && c2 < 0xE000)
      {
        cp = 0x10000 + ((cp - 0xD800) << 10) + (c2 - 0xDC00);
        i++;
      }
    }
    if (cp < 0x80) res += (char)cp;
    else if (cp < 0x800)
    {
      res += (char)(0xC0 | (cp >> 6));
      res += (char)(0x80 | (cp & 0x3F));
    }
    else if (cp < 0x10000)
    {
      res += (char)(0xE0 | (cp >> 12));
      res += (char)(0x80 | ((cp >> 6) & 0x3F));
      res += (char)(0x80 | (cp & 0x3F));
    }
    else
    {
      res += (char)(0xF0 | (cp >> 18));
      res += (char)(0x80 | ((cp >> 12) & 0x3F));
      res += (char)(0x80 | ((cp >> 6) & 0x3F));
      res += (char)(0x80 | (cp & 0x3F));
    }
  }
  return res;
}

std::string Utf16ToUtf8(const std::vector<UInt16> &s)
{
  return Utf16ToUtf8(s.data(), s.size());
}

