#pragma once
// Console output abstraction: 7-Zip lets the user route the "output", "error"
// and "progress" streams independently with -bs{o|e|p}{0|1|2}.

#include "common.h"
#include <string>

enum EStreamSel { kStream_Disabled = 0, kStream_StdOut = 1, kStream_StdErr = 2 };

class CStdOutStream
{
  FILE *_f;
public:
  CStdOutStream() : _f(NULL) {}
  void SetFile(FILE *f) { _f = f; }
  FILE *GetFile() const { return _f; }
  bool IsEnabled() const { return _f != NULL; }
  CStdOutStream &operator<<(const char *s) { if (_f) fputs(s, _f); return *this; }
  CStdOutStream &operator<<(const std::string &s) { if (_f) fwrite(s.data(), 1, s.size(), _f); return *this; }
  CStdOutStream &operator<<(char c) { if (_f) fputc(c, _f); return *this; }
  CStdOutStream &operator<<(UInt64 v) { if (_f) fputs(NumToString(v).c_str(), _f); return *this; }
  CStdOutStream &operator<<(int v) { if (_f) fputs(NumToString((UInt64)v).c_str(), _f); return *this; }
  void Flush() { if (_f) fflush(_f); }
  void NewLine() { if (_f) fputc('\n', _f); }
};

extern CStdOutStream g_Out;   // normal output
extern CStdOutStream g_Err;   // error output
extern CStdOutStream g_Pct;   // progress output

void SetupStreams(int outSel, int errSel, int pctSel);

