CStdOutStream g_Out;
CStdOutStream g_Err;
CStdOutStream g_Pct;

static FILE *SelToFile(int sel)
{
  if (sel == kStream_StdOut) return stdout;
  if (sel == kStream_StdErr) return stderr;
  return NULL;
}

void SetupStreams(int outSel, int errSel, int pctSel)
{
  g_Out.SetFile(SelToFile(outSel));
  g_Err.SetFile(SelToFile(errSel));
  g_Pct.SetFile(SelToFile(pctSel));
}

