#pragma once
#include "common.h"
#include <string>

UInt32 Crc32Update(UInt32 crc, const void *data, size_t size);
inline UInt32 Crc32Calc(const void *data, size_t size) { return Crc32Update(0xFFFFFFFF, data, size) ^ 0xFFFFFFFF; }

UInt64 Crc64Update(UInt64 crc, const void *data, size_t size);
inline UInt64 Crc64Calc(const void *data, size_t size)
  { return Crc64Update(0xFFFFFFFFFFFFFFFFULL, data, size) ^ 0xFFFFFFFFFFFFFFFFULL; }

// ------------------------------------------------------------------- SHA1
struct CSha1
{
  UInt32 state[5];
  UInt64 count;
  Byte buf[64];
  CSha1() { Init(); }
  void Init();
  void Update(const void *data, size_t size);
  void Final(Byte digest[20]);
};

// ----------------------------------------------------------------- SHA256
struct CSha256
{
  UInt32 state[8];
  UInt64 count;
  Byte buf[64];
  CSha256() { Init(); }
  void Init();
  void Update(const void *data, size_t size);
  void Final(Byte digest[32]);
};

// ------------------------------------------------------------------ XXH64
struct CXxh64
{
  UInt64 v[4];
  UInt64 total;
  Byte buf[32];
  unsigned bufLen;
  CXxh64() { Init(); }
  void Init();
  void Update(const void *data, size_t size);
  UInt64 Final();
};

// ------------------------------------------------------ generic hasher API
enum EHashId { kHashCrc32, kHashCrc64, kHashSha256, kHashSha1, kHashXxh64 };

struct CHasher
{
  EHashId id;
  UInt32 crc32;
  UInt64 crc64;
  CSha1 sha1;
  CSha256 sha256;
  CXxh64 xxh64;

  void Init(EHashId hid);
  void Update(const void *data, size_t size);
  // Returns the digest bytes (big-endian order as 7-Zip prints them)
  void Final(std::vector<Byte> &digest);
  unsigned DigestSize() const;
  const char *Name() const;
  bool IsUpperHex() const;   // CRC/XXH are printed with uppercase hex
};

