void CHasher::Update(const void *data, size_t size)
{
  switch (id)
  {
    case kHashCrc32:  crc32 = Crc32Update(crc32, data, size); break;
    case kHashCrc64:  crc64 = Crc64Update(crc64, data, size); break;
    case kHashSha1:   sha1.Update(data, size); break;
    case kHashSha256: sha256.Update(data, size); break;
    case kHashXxh64:  xxh64.Update(data, size); break;
  }
}

void CHasher::Final(std::vector<Byte> &digest)
{
  digest.clear();
  switch (id)
  {
    case kHashCrc32:
    {
      UInt32 v = crc32 ^ 0xFFFFFFFF;
      for (int i = 3; i >= 0; i--) digest.push_back((Byte)(v >> (i * 8)));
      break;
    }
    case kHashCrc64:
    {
      UInt64 v = crc64 ^ 0xFFFFFFFFFFFFFFFFULL;
      for (int i = 7; i >= 0; i--) digest.push_back((Byte)(v >> (i * 8)));
