    case kHashSha1:   { Byte d[20]; sha1.Final(d); digest.assign(d, d + 20); break; }
    case kHashSha256: { Byte d[32]; sha256.Final(d); digest.assign(d, d + 32); break; }
    case kHashXxh64:
    {
      UInt64 v = xxh64.Final();
      for (int i = 7; i >= 0; i--) digest.push_back((Byte)(v >> (i * 8)));
      break;
    }
  }
}

unsigned CHasher::DigestSize() const
{
  switch (id)
  {
    case kHashCrc32: return 4;
    case kHashCrc64: return 8;
    case kHashSha1: return 20;
    case kHashSha256: return 32;
    case kHashXxh64: return 8;
  }
  return 4;
}

const char *CHasher::Name() const
{
  switch (id)
  {
    case kHashCrc32: return "CRC32";
    case kHashCrc64: return "CRC64";
    case kHashSha1: return "SHA1";
    case kHashSha256: return "SHA256";
    case kHashXxh64: return "XXH64";
  }
