  state[0] += a; state[1] += b; state[2] += c; state[3] += d;
  state[4] += e; state[5] += f; state[6] += g; state[7] += h;
}

void CSha256::Update(const void *data, size_t size)
{
  const Byte *p = (const Byte *)data;
  unsigned pos = (unsigned)(count & 63);
  count += size;
  if (pos)
  {
    unsigned need = 64 - pos;
    if (size < need) { memcpy(buf + pos, p, size); return; }
    memcpy(buf + pos, p, need);
    Sha256Block(state, buf);
    p += need; size -= need;
  }
  while (size >= 64) { Sha256Block(state, p); p += 64; size -= 64; }
  memcpy(buf, p, size);
}

void CSha256::Final(Byte digest[32])
{
  UInt64 bits = count << 3;
  Byte pad[72];
  unsigned pos = (unsigned)(count & 63);
  unsigned padLen = (pos < 56) ? (56 - pos) : (120 - pos);
  memset(pad, 0, sizeof(pad));
  pad[0] = 0x80;
  Byte lenBuf[8];
  for (int i = 0; i < 8; i++) lenBuf[i] = (Byte)(bits >> (56 - i * 8));
  Update(pad, padLen);
  Update(lenBuf, 8);
  for (int i = 0; i < 8; i++)
  {
    digest[i * 4]     = (Byte)(state[i] >> 24);
    digest[i * 4 + 1] = (Byte)(state[i] >> 16);
    digest[i * 4 + 2] = (Byte)(state[i] >> 8);
    digest[i * 4 + 3] = (Byte)(state[i]);
  }
}

// ------------------------------------------------------------------- XXH64
static const UInt64 kP1 = 0x9E3779B185EBCA87ULL;
static const UInt64 kP2 = 0xC2B2AE3D27D4EB4FULL;
static const UInt64 kP3 = 0x165667B19E3779F9ULL;
static const UInt64 kP4 = 0x85EBCA77C2B2AE63ULL;
static const UInt64 kP5 = 0x27D4EB2F165667C5ULL;

static inline UInt64 Rotl64(UInt64 x, unsigned n) { return (x << n) | (x >> (64 - n)); }
static inline UInt64 Rd64(const Byte *p)
{
  return (UInt64)p[0] | ((UInt64)p[1] << 8) | ((UInt64)p[2] << 16) | ((UInt64)p[3] << 24)
       | ((UInt64)p[4] << 32) | ((UInt64)p[5] << 40) | ((UInt64)p[6] << 48) | ((UInt64)p[7] << 56);
}
static inline UInt32 Rd32(const Byte *p)
{
  return (UInt32)p[0] | ((UInt32)p[1] << 8) | ((UInt32)p[2] << 16) | ((UInt32)p[3] << 24);
}
static inline UInt64 XxhRound(UInt64 acc, UInt64 input)
{
  acc += input * kP2;
  acc = Rotl64(acc, 31);
  return acc * kP1;
}
static inline UInt64 XxhMerge(UInt64 acc, UInt64 val)
{
  val = XxhRound(0, val);
  acc ^= val;
  return acc * kP1 + kP4;
}

void CXxh64::Init()
{
  v[0] = kP1 + kP2; v[1] = kP2; v[2] = 0; v[3] = 0ULL - kP1;
  total = 0; bufLen = 0;
}

void CXxh64::Update(const void *data, size_t size)
{
  const Byte *p = (const Byte *)data;
  total += size;
  if (bufLen + size < 32) { memcpy(buf + bufLen, p, size); bufLen += (unsigned)size; return; }
  if (bufLen)
  {
    unsigned need = 32 - bufLen;
    memcpy(buf + bufLen, p, need);
    for (int i = 0; i < 4; i++) v[i] = XxhRound(v[i], Rd64(buf + i * 8));
    p += need; size -= need; bufLen = 0;
  }
  while (size >= 32)
  {
    for (int i = 0; i < 4; i++) v[i] = XxhRound(v[i], Rd64(p + i * 8));
    p += 32; size -= 32;
  }
  memcpy(buf, p, size);
  bufLen = (unsigned)size;
}

UInt64 CXxh64::Final()
{
  UInt64 h;
  if (total >= 32)
  {
    h = Rotl64(v[0], 1) + Rotl64(v[1], 7) + Rotl64(v[2], 12) + Rotl64(v[3], 18);
    h = XxhMerge(h, v[0]);
    h = XxhMerge(h, v[1]);
    h = XxhMerge(h, v[2]);
    h = XxhMerge(h, v[3]);
  }
  else
    h = v[2] /* seed 0 */ + kP5;
  h += total;

  const Byte *p = buf;
  size_t len = bufLen;
  while (len >= 8)
  {
    h ^= XxhRound(0, Rd64(p));
    h = Rotl64(h, 27) * kP1 + kP4;
    p += 8; len -= 8;
  }
  if (len >= 4)
  {
    h ^= (UInt64)Rd32(p) * kP1;
    h = Rotl64(h, 23) * kP2 + kP3;
    p += 4; len -= 4;
  }
  while (len)
  {
    h ^= (UInt64)(*p) * kP5;
    h = Rotl64(h, 11) * kP1;
    p++; len--;
  }
  h ^= h >> 33; h *= kP2;
  h ^= h >> 29; h *= kP3;
  h ^= h >> 32;
  return h;
}

// ------------------------------------------------------------ CHasher glue
void CHasher::Init(EHashId hid)
{
  id = hid;
  crc32 = 0xFFFFFFFF;
  crc64 = 0xFFFFFFFFFFFFFFFFULL;
  sha1.Init();
  sha256.Init();
  xxh64.Init();
}

void CHasher::Update(const void *data, size_t size)
{
  switch (id)
  {
    case kHashCrc32:  crc32 = Crc32Update(crc32, data, size); break;
    case kHashCrc64:  crc64 = Crc64Update(crc64, data, size); break;
    case kHashSha1:   sha1.Update(data, size); break;
    case kHashSha256: sha256.Update(data, size); break;
    case kHashXxh64:  xxh64.Update(data, size); break;
  }
}

void CHasher::Final(std::vector<Byte> &digest)
{
  digest.clear();
  switch (id)
  {
    case kHashCrc32:
    {
      UInt32 v = crc32 ^ 0xFFFFFFFF;
      for (int i = 3; i >= 0; i--) digest.push_back((Byte)(v >> (i * 8)));
      break;
    }
    case kHashCrc64:
    {
      UInt64 v = crc64 ^ 0xFFFFFFFFFFFFFFFFULL;
      for (int i = 7; i >= 0; i--) digest.push_back((Byte)(v >> (i * 8)));
      break;
    }
    case kHashSha1:   { Byte d[20]; sha1.Final(d); digest.assign(d, d + 20); break; }
    case kHashSha256: { Byte d[32]; sha256.Final(d); digest.assign(d, d + 32); break; }
    case kHashXxh64:
    {
      UInt64 v = xxh64.Final();
      for (int i = 7; i >= 0; i--) digest.push_back((Byte)(v >> (i * 8)));
      break;
    }
  }
}

unsigned CHasher::DigestSize() const
{
  switch (id)
  {
    case kHashCrc32: return 4;
    case kHashCrc64: return 8;
    case kHashSha1: return 20;
    case kHashSha256: return 32;
    case kHashXxh64: return 8;
  }
  return 4;
}

const char *CHasher::Name() const
{
  switch (id)
  {
    case kHashCrc32: return "CRC32";
    case kHashCrc64: return "CRC64";
    case kHashSha1: return "SHA1";
    case kHashSha256: return "SHA256";
    case kHashXxh64: return "XXH64";
  }
  return "CRC32";
}

bool CHasher::IsUpperHex() const
{
  return id == kHashCrc32 || id == kHashCrc64 || id == kHashXxh64;
}

