static const CSwitchForm kSwitchForms[kSwId_Count] =
{
  { "?",     kSw_Simple, false, 0, 0, NULL },
  { "h",     kSw_Simple, false, 0, 0, NULL },
  { "-help", kSw_Simple, false, 0, 0, NULL },

