struct CSwitchResult
{
  bool ThereIs;
  bool WithMinus;
  std::string PostChars;
  std::vector<std::string> PostStrings;
  CSwitchResult() : ThereIs(false), WithMinus(false) {}
};

static bool MatchKeyNoCase(const std::string &s, const char *key, size_t &keyLen)
{
  keyLen = strlen(key);
  if (s.size() < keyLen) return false;
  for (size_t i = 0; i < keyLen; i++)
  {
    char c1 = s[i], c2 = key[i];
    if (c1 >= 'A' && c1 <= 'Z') c1 = (char)(c1 - 'A' + 'a');
    if (c2 >= 'A' && c2 <= 'Z') c2 = (char)(c2 - 'A' + 'a');
    if (c1 != c2) return false;
  }
  return true;
}

// ---------------------------------------------------------------------------

static void ParseSwitch(const std::string &sw /* without leading '-' */,
                        const std::string &full,
                        CSwitchResult results[kSwId_Count])
{
  // find the table entry with the longest matching key
  int best = -1;
  size_t bestLen = 0;
  for (int i = 0; i < kSwId_Count; i++)
  {
    size_t keyLen;
    if (MatchKeyNoCase(sw, kSwitchForms[i].Key, keyLen))
      if (best < 0 || keyLen > bestLen) { best = i; bestLen = keyLen; }
  }
  if (best < 0)
    throw CCmdLineError("Unknown switch:", full);

  const CSwitchForm &form = kSwitchForms[best];
  CSwitchResult &res = results[best];
  if (res.ThereIs && !form.Multi)
    throw CCmdLineError("Multiple instances for switch:", full);

  std::string post = sw.substr(bestLen);

  switch (form.Type)
  {
    case kSw_Simple:
      if (!post.empty()) throw CCmdLineError("Too long switch:", full);
      break;
    case kSw_Minus:
      if (post.empty()) res.WithMinus = false;
      else if (post == "-") res.WithMinus = true;
      else if (post.size() > 1) throw CCmdLineError("Too long switch:", full);
      else throw CCmdLineError("Incorrect switch postfix:", full);
      break;
    case kSw_Char:
      if (post.size() < form.MinLen) throw CCmdLineError("Too short switch:", full);
      if (form.MaxLen != 0 && post.size() > form.MaxLen)
        throw CCmdLineError("Too long switch:", full);
      for (size_t i = 0; i < post.size(); i++)
      {
        char c = post[i];
        char lc = (c >= 'A' && c <= 'Z') ? (char)(c - 'A' + 'a') : c;
        if (!strchr(form.Chars, lc))
          throw CCmdLineError("Incorrect switch postfix:", full);
      }
      res.PostChars = post;
      break;
    case kSw_String:
      if (post.size() < form.MinLen) throw CCmdLineError("Too short switch:", full);
      res.PostStrings.push_back(post);
      break;
  }
  res.ThereIs = true;
}

// ---------------------------------------------------------------------------

static bool ParseUInt(const std::string &s, UInt64 &value)
{
  if (s.empty()) return false;
  value = 0;
  for (size_t i = 0; i < s.size(); i++)
  {
    if (s[i] < '0' || s[i] > '9') return false;
    value = value * 10 + (UInt64)(s[i] - '0');
  }
  return true;
}

static void AddCensorItem(std::vector<CCensorPair> &v, const std::string &spec,
                          const std::string &full, bool include)
{
  // spec: [r[-|0]][m[-|2]][w[-]]{@listfile|!wildcard}
  size_t i = 0;
  CCensorPair p;
  p.include = include;
  p.recursive = false;
  p.wildcard = true;
  p.fromListFile = false;
  for (;;)
  {
    if (i >= spec.size()) throw CCmdLineError("Incorrect wildcard type marker", full);
    char c = spec[i];
    if (c == 'r' || c == 'R')
    {
      i++;
      p.recursive = true;
      if (i < spec.size() && (spec[i] == '-' || spec[i] == '0'))
      {
        if (spec[i] == '-') p.recursive = false;
        i++;
      }
      continue;
    }
    if (c == 'm' || c == 'M')
    {
      i++;
      if (i < spec.size() && (spec[i] == '-' || spec[i] == '2')) i++;
      continue;
    }
    if (c == 'w' || c == 'W')
    {
      i++;
      if (i < spec.size() && spec[i] == '-') { p.wildcard = false; i++; }
      continue;
    }
    break;
  }
  if (i >= spec.size()) throw CCmdLineError("Incorrect wildcard type marker", full);
  char kind = spec[i++];
  std::string rest = spec.substr(i);
  if (kind == '@') { p.fromListFile = true; p.name = rest; }
  else if (kind == '!') { p.name = rest; }
  else throw CCmdLineError("Incorrect wildcard type marker", full);
  v.push_back(p);
}

void ParseCommandLine(const std::vector<std::string> &args, COptions &op)
{
  CSwitchResult res[kSwId_Count];
  bool stopSwitch = false;

  for (size_t i = 0; i < args.size(); i++)
  {
    const std::string &s = args[i];
    if (!stopSwitch && s.size() >= 2 && s[0] == '-')
    {
      if (s == "--") { stopSwitch = true; continue; }
      ParseSwitch(s.substr(1), s, res);
      continue;
    }
    if (!stopSwitch && s == "-")
    {
      op.NonSwitch.push_back(s);
      continue;
    }
    op.NonSwitch.push_back(s);
  }

  if (res[kSwId_Help1].ThereIs || res[kSwId_Help2].ThereIs || res[kSwId_Help3].ThereIs)
  {
    op.HelpMode = true;
    return;
  }

  // --- stream selection
  if (res[kSwId_BSO].ThereIs) op.OutSel = res[kSwId_BSO].PostChars[0] - '0';
  if (res[kSwId_BSE].ThereIs) op.ErrSel = res[kSwId_BSE].PostChars[0] - '0';
  if (res[kSwId_BSP].ThereIs) op.PctSel = res[kSwId_BSP].PostChars[0] - '0';

