  op.ShowTime = res[kSwId_BT].ThereIs;
  op.DisableProgress = res[kSwId_BD].ThereIs;
  op.TechMode = res[kSwId_Slt].ThereIs;
  op.YesToAll = res[kSwId_Yes].ThereIs;
  op.StdOutMode = res[kSwId_StdOut].ThereIs;
  if (res[kSwId_StdIn].ThereIs) { op.StdInMode = true; op.StdInFileName = res[kSwId_StdIn].PostStrings[0]; }
  op.DisableArchiveName = res[kSwId_NoArName].ThereIs;
  op.DeleteAfterCompress = res[kSwId_SDel].ThereIs;
  op.StoreSymLinks = res[kSwId_SymLinks].ThereIs && !res[kSwId_SymLinks].WithMinus;
  op.StoreHardLinks = res[kSwId_HardLinks].ThereIs && !res[kSwId_HardLinks].WithMinus;
  if (res[kSwId_CaseSens].ThereIs) { op.CaseSensitiveSet = true; op.CaseSensitive = !res[kSwId_CaseSens].WithMinus; }
  op.LargePages = res[kSwId_LargePages].ThereIs;
  op.StopAfterOpenError = res[kSwId_StopAfterErr].ThereIs;
  op.SetArcTimeFromNewest = res[kSwId_TimeFromNewest].ThereIs;
  op.NoWildcardMatch = res[kSwId_NoWildcard].ThereIs;
  op.ElimDup = res[kSwId_ElimDup].ThereIs && !res[kSwId_ElimDup].WithMinus;
  if (res[kSwId_FullPath].ThereIs)
  {
    const std::string &v = res[kSwId_FullPath].PostStrings[0];
    op.FullPathMode = v == "2" ? 2 : 1;
  }
  if (res[kSwId_Sfx].ThereIs) { op.SfxMode = true; op.SfxModule = res[kSwId_Sfx].PostStrings[0]; }

  if (res[kSwId_OutDir].ThereIs) { op.OutputDirDefined = true; op.OutputDir = res[kSwId_OutDir].PostStrings[0]; }
