#include "fs.h"

#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>
#include <dirent.h>
#include <cerrno>
#include <cstring>
#include <cstdlib>

bool GetFileInfo(const std::string &path, CFileInfo &fi, bool followLinks)
{
  struct stat st;
  int res = followLinks ? stat(path.c_str(), &st) : lstat(path.c_str(), &st);
  if (res != 0) return false;
  fi.Path = path;
  fi.Size = (UInt64)st.st_size;
  fi.MTime = (Int64)st.st_mtime;
  fi.MTimeNs = (UInt32)st.st_mtim.tv_nsec;
  fi.ATime = (Int64)st.st_atime;
  fi.ATimeNs = (UInt32)st.st_atim.tv_nsec;
  fi.CTime = (Int64)st.st_ctime;
  fi.CTimeNs = (UInt32)st.st_ctim.tv_nsec;
  fi.Mode = (UInt32)st.st_mode;
  fi.IsDir = S_ISDIR(st.st_mode) != 0;
  fi.IsSymLink = S_ISLNK(st.st_mode) != 0;
  if (fi.IsSymLink)
  {
    char buf[4096];
    ssize_t n = readlink(path.c_str(), buf, sizeof(buf) - 1);
    if (n > 0) fi.LinkTarget.assign(buf, (size_t)n);
  }
  return true;
}

bool FileExists(const std::string &path)
{
  struct stat st;
  if (lstat(path.c_str(), &st) != 0) return false;
  return !S_ISDIR(st.st_mode);
}

bool DirExists(const std::string &path)
{
  struct stat st;
  if (stat(path.c_str(), &st) != 0) return false;
  return S_ISDIR(st.st_mode) != 0;
}

bool CreateDirs(const std::string &path)
{
  if (path.empty()) return true;
  std::string cur;
  size_t i = 0;
  if (path[0] == '/') { cur = "/"; i = 1; }
  while (i <= path.size())
  {
    if (i == path.size() || path[i] == '/')
    {
      if (!cur.empty() && cur != "/" && !DirExists(cur))
        if (mkdir(cur.c_str(), 0777) != 0 && !DirExists(cur))
          return false;
      if (i == path.size()) break;
      if (!cur.empty() && cur != "/") cur += '/';
      i++;
      continue;
    }
    cur += path[i];
    i++;
  }
  return DirExists(path) || path.empty();
}

bool ReadWholeFile(const std::string &path, std::vector<Byte> &buf)
{
  FILE *f = fopen(path.c_str(), "rb");
  if (!f) return false;
  buf.clear();
  Byte tmp[65536];
  for (;;)
  {
    size_t n = fread(tmp, 1, sizeof(tmp), f);
    if (n == 0) break;
    buf.insert(buf.end(), tmp, tmp + n);
  }
  fclose(f);
  return true;
}

// ---------------------------------------------------------------------------

static bool WildMatchRec(const char *p, const char *n, bool cs)
{
  while (*p)
  {
    if (*p == '*')
    {
      p++;
      if (!*p) return true;
      for (const char *t = n; ; t++)
      {
        if (WildMatchRec(p, t, cs)) return true;
        if (!*t) return false;
      }
    }
    if (!*n) return false;
    if (*p != '?')
    {
      char c1 = *p, c2 = *n;
      if (!cs)
      {
        if (c1 >= 'A' && c1 <= 'Z') c1 = (char)(c1 - 'A' + 'a');
        if (c2 >= 'A' && c2 <= 'Z') c2 = (char)(c2 - 'A' + 'a');
      }
      if (c1 != c2) return false;
    }
    p++; n++;
  }
  return *n == 0;
}

bool WildcardMatch(const std::string &pattern, const std::string &name, bool caseSensitive)
{
  return WildMatchRec(pattern.c_str(), name.c_str(), caseSensitive);
}

std::string GetFileName(const std::string &path)
{
  size_t p = path.rfind('/');
  if (p == std::string::npos) return path;
  return path.substr(p + 1);
}

std::string GetDirPrefix(const std::string &path)
{
  size_t p = path.rfind('/');
  if (p == std::string::npos) return std::string();
  return path.substr(0, p + 1);
}

