#include "app.h"
#include "console.h"

#include <dirent.h>
#include <cerrno>
#include <cstring>
#include <algorithm>

std::string PluralFiles(UInt64 n)
{
  return NumToString(n) + (n == 1 ? " file" : " files");
}

std::string PluralFolders(UInt64 n)
{
  return NumToString(n) + (n == 1 ? " folder" : " folders");
}

std::string ScanSummary(UInt64 numDirs, UInt64 numFiles, UInt64 size)
{
  std::string s;
  if (numDirs != 0) s += PluralFolders(numDirs) + ", ";
  s += PluralFiles(numFiles) + ", ";
  s += NumToString(size) + " bytes";
  if (size != 0) s += " (" + KibString(size) + ")";
  return s;
}

// ---------------------------------------------------------------------------

static bool IsExcluded(const std::vector<CScanSpec> &excludes, const std::string &path,
                       const std::string &baseName, bool caseSensitive)
{
  for (size_t i = 0; i < excludes.size(); i++)
  {
    const CScanSpec &e = excludes[i];
    if (WildcardMatch(e.Name, baseName, caseSensitive)) return true;
    if (WildcardMatch(e.Name, path, caseSensitive)) return true;
  }
  return false;
}

static void AddDirRecursive(const std::string &fullPath, const std::string &arcPath,
                            const std::vector<CScanSpec> &excludes, bool caseSensitive,
                            const std::string &skipFile, CScanResult &res);

static void AddOneItem(const std::string &fullPath, const std::string &arcPath,
                       const CFileInfo &fi,
                       const std::vector<CScanSpec> &excludes, bool caseSensitive,
                       const std::string &skipFile, CScanResult &res)
{
  CDirItem di;
  di.Name = arcPath;
  di.FullPath = fullPath;
  di.Size = fi.IsDir ? 0 : fi.Size;
  di.MTime = fi.MTime;
  di.MTimeNs = fi.MTimeNs;
  di.Mode = fi.Mode;
  di.IsDir = fi.IsDir;
  di.IsSymLink = fi.IsSymLink;
  di.LinkTarget = fi.LinkTarget;
  res.Items.push_back(di);
  if (fi.IsDir) { res.NumDirs++; AddDirRecursive(fullPath, arcPath, excludes, caseSensitive, skipFile, res); }
  else { res.NumFiles++; res.TotalSize += fi.Size; }
}

static void AddDirRecursive(const std::string &fullPath, const std::string &arcPath,
                            const std::vector<CScanSpec> &excludes, bool caseSensitive,
                            const std::string &skipFile, CScanResult &res)
{
  DIR *d = opendir(fullPath.c_str());
  if (!d) { CScanError e; e.Path = fullPath; e.Errno = errno; res.Errors.push_back(e); return; }
  struct dirent *de;
  while ((de = readdir(d)) != NULL)
  {
    if (strcmp(de->d_name, ".") == 0 || strcmp(de->d_name, "..") == 0) continue;
    std::string name = de->d_name;
    std::string fp = fullPath + "/" + name;
    std::string ap = arcPath.empty() ? name : (arcPath + "/" + name);
    if (!skipFile.empty() && fp == skipFile) continue;
    if (IsExcluded(excludes, ap, name, caseSensitive)) continue;
    CFileInfo fi;
    if (!GetFileInfo(fp, fi, false))
    {
      CScanError e; e.Path = fp; e.Errno = errno; res.Errors.push_back(e);
      continue;
    }
    if (fi.IsSymLink)
    {
      CFileInfo fi2;
      if (GetFileInfo(fp, fi2, true)) { fi2.IsSymLink = true; fi2.LinkTarget = fi.LinkTarget; fi = fi2; }
    }
    AddOneItem(fp, ap, fi, excludes, caseSensitive, skipFile, res);
  }
  closedir(d);
}

void ScanItems(const std::vector<CScanSpec> &specs,
               const std::vector<CScanSpec> &excludes,
               bool caseSensitive,
               const std::string &skipFile,
               CScanResult &res)
{
  for (size_t i = 0; i < specs.size(); i++)
  {
