    if (fi.IsSymLink)
    {
      CFileInfo fi2;
      if (GetFileInfo(fp, fi2, true)) { fi2.IsSymLink = true; fi2.LinkTarget = fi.LinkTarget; fi = fi2; }
    }
    AddOneItem(fp, ap, fi, excludes, caseSensitive, skipFile, res);
  }
  closedir(d);
}

