// ---------------------------------------------------------------------------
// "h" : hash calculation
// ---------------------------------------------------------------------------

struct CHashSum
{
  std::vector<Byte> Sum;      // little endian multiprecision
  UInt32 Carry;
  CHashSum() : Carry(0) {}
  void Init(unsigned size) { Sum.assign(size, 0); Carry = 0; }
  void Add(const std::vector<Byte> &digestLe)
  {
    unsigned c = 0;
    for (size_t i = 0; i < Sum.size(); i++)
