  {
    for (size_t i = internalDigest.size(); i > 0; i--)
    {
      Byte b = internalDigest[i - 1];
      s += tab[b >> 4]; s += tab[b & 0xF];
    }
  }
  else
  {
    for (size_t i = 0; i < internalDigest.size(); i++)
    {
