  {
    std::string s = ToLowerAscii(specs[i]);
    if (s.empty()) { ids.push_back(kHashCrc32); continue; }
    if (s == "*")
    {
      ids.push_back(kHashCrc32); ids.push_back(kHashCrc64);
      ids.push_back(kHashSha256); ids.push_back(kHashSha1); ids.push_back(kHashXxh64);
