  return true;
}

int CmdHash(COptions &op)
{
  std::vector<EHashId> ids;
  ParseHashMethods(op.HashMethods, ids);

  // build scan specs from the non-switch args (skip [0] = command)
  std::vector<CScanSpec> specs, excludes;
  for (size_t i = 1; i < op.NonSwitch.size(); i++)
  {
    CScanSpec sp;
    sp.Name = op.NonSwitch[i];
    sp.Recursive = (op.RecurseType == 1);
    sp.IsWildcard = sp.Name.find('*') != std::string::npos || sp.Name.find('?') != std::string::npos;
    specs.push_back(sp);
  }
  for (size_t i = 0; i < op.Censor.size(); i++)
  {
    CScanSpec sp;
    sp.Name = op.Censor[i].name;
    sp.Recursive = op.Censor[i].recursive;
    sp.IsWildcard = sp.Name.find('*') != std::string::npos || sp.Name.find('?') != std::string::npos;
    (op.Censor[i].include ? specs : excludes).push_back(sp);
  }
  if (specs.empty())
  {
    CScanSpec sp; sp.Name = "*"; sp.Recursive = false; sp.IsWildcard = true;
    specs.push_back(sp);
  }

  g_Out << "\nScanning\n";
  CScanResult sr;
  ScanItems(specs, excludes, op.CaseSensitive, "", sr);
  g_Out << ScanSummary(sr.NumDirs, sr.NumFiles, sr.TotalSize) << "\n";

  // ------------------------------------------------------------------ header
  std::vector<CHasher> hashers(ids.size());
  std::vector<CHashSum> dataSums(ids.size()), nameSums(ids.size());
  std::string header, sep;
  for (size_t k = 0; k < ids.size(); k++)
  {
    CHasher tmp; tmp.Init(ids[k]);
    unsigned w = tmp.DigestSize() * 2;
    header += PadRight(tmp.Name(), w) + " ";
    sep += std::string(w, '-') + " ";
    dataSums[k].Init(tmp.DigestSize());
    nameSums[k].Init(tmp.DigestSize());
  }
  header += PadRight("", 9) + "Size" + "  " + "Name";
  sep += std::string(13, '-') + "  " + std::string(12, '-');

  g_Out << "\n" << header << "\n" << sep << "\n";

  // -------------------------------------------------------------- processing
  std::vector<Byte> buf(1 << 16);
  bool ok = true;
  for (size_t i = 0; i < sr.Items.size(); i++)
  {
    const CDirItem &it = sr.Items[i];
    std::string line;
    if (it.IsDir)
    {
      for (size_t k = 0; k < ids.size(); k++)
      {
        CHasher tmp; tmp.Init(ids[k]);
        line += std::string(tmp.DigestSize() * 2, ' ') + " ";
      }
      line += PadRight("", 13) + "  " + it.Name + "/";
      g_Out << line << "\n";
      // name hash uses a zero digest with a dir marker
      for (size_t k = 0; k < ids.size(); k++)
      {
        CHasher nh; nh.Init(ids[k]);
        Byte pre[16]; memset(pre, 0, sizeof(pre)); pre[0] = 1;
        nh.Update(pre, 16);
        std::vector<Byte> zero(nh.DigestSize(), 0);
        nh.Update(zero.data(), zero.size());
        std::vector<UInt16> w = Utf8ToUtf16(it.Name);
        for (size_t q = 0; q < w.size(); q++)
        { Byte t[2] = { (Byte)(w[q] & 0xFF), (Byte)(w[q] >> 8) }; nh.Update(t, 2); }
        std::vector<Byte> d;
        GetInternalDigest(nh, d);
        nameSums[k].Add(d);
      }
      continue;
    }

    for (size_t k = 0; k < ids.size(); k++) hashers[k].Init(ids[k]);
    FILE *f = fopen(it.FullPath.c_str(), "rb");
    if (!f) { ok = false; continue; }
    for (;;)
    {
      size_t n = fread(buf.data(), 1, buf.size(), f);
      if (n == 0) break;
      for (size_t k = 0; k < ids.size(); k++) hashers[k].Update(buf.data(), n);
    }
    fclose(f);

    for (size_t k = 0; k < ids.size(); k++)
    {
      std::vector<Byte> d;
      GetInternalDigest(hashers[k], d);
      line += DigestToString(hashers[k], d) + " ";
      dataSums[k].Add(d);

      CHasher nh; nh.Init(ids[k]);
      Byte pre[16]; memset(pre, 0, sizeof(pre));
      nh.Update(pre, 16);
      nh.Update(d.data(), d.size());
      std::vector<UInt16> w = Utf8ToUtf16(it.Name);
      for (size_t q = 0; q < w.size(); q++)
      { Byte t[2] = { (Byte)(w[q] & 0xFF), (Byte)(w[q] >> 8) }; nh.Update(t, 2); }
      std::vector<Byte> nd;
      GetInternalDigest(nh, nd);
      nameSums[k].Add(nd);
    }
    line += NumToStringPad(it.Size, 13) + "  " + it.Name;
    g_Out << line << "\n";
  }

  g_Out << sep << "\n";

  bool single = (sr.NumFiles == 1 && sr.NumDirs == 0);

  // ------------------------------------------------------------------ totals
  {
    std::string line;
    for (size_t k = 0; k < ids.size(); k++)
    {
      CHasher tmp; tmp.Init(ids[k]);
      std::string s = DigestToString(tmp, dataSums[k].Sum);
      if (!single) s += "-" + HexU32(dataSums[k].Carry);
      line += s + " ";
    }
    line += NumToStringPad(sr.TotalSize, 13) + "  ";
    g_Out << line << "\n";
  }

  g_Out << "\n";
  if (sr.NumDirs != 0) g_Out << "Folders: " << sr.NumDirs << "\n";
  if (sr.NumFiles != 1 || sr.NumDirs != 0) g_Out << "Files: " << sr.NumFiles << "\n";
  g_Out << "Size: " << sr.TotalSize << "\n";

  for (size_t k = 0; k < ids.size(); k++)
  {
    CHasher tmp; tmp.Init(ids[k]);
    g_Out << "\n";
    std::string label = PadRight(tmp.Name(), 6) + " for data:";
    std::string s = DigestToString(tmp, dataSums[k].Sum);
    if (!single) s += "-" + HexU32(dataSums[k].Carry);
    g_Out << PadRight(label, 30) << s << "\n";
    if (!single)
    {
      std::string l2 = PadRight(tmp.Name(), 6) + " for data and names:";
      std::string s2 = DigestToString(tmp, nameSums[k].Sum);
      s2 += "-" + HexU32(nameSums[k].Carry);
      g_Out << PadRight(l2, 30) << s2 << "\n";
    }
  }

  g_Out << "\nEverything is Ok\n";
  return ok ? kExit_Ok : kExit_Fatal;
}

