static bool ParseCommand(const std::string &s, ECommand &cmd)
{
  std::string t = ToLowerAscii(s);
  if (t == "a")  { cmd = kCmd_Add; return true; }
  if (t == "b")  { cmd = kCmd_Bench; return true; }
  if (t == "d")  { cmd = kCmd_Delete; return true; }
  if (t == "e")  { cmd = kCmd_Extract; return true; }
  if (t == "h")  { cmd = kCmd_Hash; return true; }
  if (t == "i")  { cmd = kCmd_Info; return true; }
  if (t == "l")  { cmd = kCmd_List; return true; }
  if (t == "rn") { cmd = kCmd_Rename; return true; }
  if (t == "t")  { cmd = kCmd_Test; return true; }
  if (t == "u")  { cmd = kCmd_Update; return true; }
  if (t == "x")  { cmd = kCmd_ExtractFull; return true; }
  return false;
}

int MainCommand(COptions &op)
{
  if (op.NonSwitch.empty())
    throw CCmdLineError("The command must be specified");

  if (!ParseCommand(op.NonSwitch[0], op.Command))
    throw CCmdLineError("Unsupported command:", op.NonSwitch[0]);
  op.CommandDefined = true;
  op.CommandString = op.NonSwitch[0];

  switch (op.Command)
  {
    case kCmd_Info: return CmdInfo(op);
    case kCmd_Hash: return CmdHash(op);
    case kCmd_Bench: return CmdBench(op);
    default: break;
  }
  return CmdArchive(op);
}

